import http from'node:http';import{clusterReadiness}from'../../../deploy/cluster-readiness.mjs';import{trackClusterRequest}from'../../../deploy/cluster-request-lifecycle.mjs';
const server=http.createServer(async(req,res)=>{const response=await trackClusterRequest(async()=>{if(req.url==='/api/ready')return new Response('{}',{status:await clusterReadiness(true)?200:503});if(req.url==='/received-then-crash'){process.send?.({type:'fixture.received'});setImmediate(()=>process.exit(12));return new Promise(()=>{});}if(req.url==='/slow'||req.url==='/orphan'){process.send?.({type:'fixture.slow.started'});await new Promise(r=>setTimeout(r,250));if(req.url==='/orphan')process.send?.({type:'fixture.orphan.finished'});}return Response.json({slot:process.env.WMS_CLUSTER_SLOT,pool:Number(process.env.WMS_DB_POOL_MAX),pid:process.pid,unsafeFlagsPresent:['NEXT_MANUAL_SIG_HANDLE','NEXT_PRIVATE_WORKER','NEXT_PRIVATE_PROMPT_OUTPUT','__NEXT_PRIVATE_STANDALONE_CONFIG'].some(key=>key in process.env),operationsBindingPresent:['BOOTSTRAP_DATABASE_URL','MIGRATION_DATABASE_URL','TEST_DATABASE_URL'].some(key=>key in process.env)});});if(!res.destroyed){res.writeHead(response.status,Object.fromEntries(response.headers));res.end(Buffer.from(await response.arrayBuffer()));}});
server.listen(Number(process.env.PORT),'127.0.0.1');process.on('SIGTERM',()=>server.close(()=>process.exit(0)));
